+	}
+	writeStateForPid(t, pid)
+	writePostmasterPid(t, pid)
+
+	state, err := GetState()
+	if err != nil {
+		t.Fatalf("GetState: %v", err)
+	}
+	if state != nil {
+		t.Fatalf("GetState reported zombie pid %d as a running database", pid)
+	}
+
+	state, err = GetState()
+	if err != nil {
+		t.Fatalf("GetState after the state file was removed: %v", err)
+	}
